package com.petpalette;

import java.awt.Color;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

public class PetProfile
{
    private String id;
    private String petKey;
    private String name;
    private boolean enabled;
    private Map<String, Integer> colours = new LinkedHashMap<>();

    private Set<String> overriddenRegions = new LinkedHashSet<>();

    private Map<String, String> regionNames = new LinkedHashMap<>();

    public PetProfile()
    {
        // Gson
    }

    public static PetProfile create(PetDefinition definition, String name)
    {
        PetProfile profile = new PetProfile();
        profile.id = UUID.randomUUID().toString();
        profile.petKey = definition.getKey();
        profile.name = name;
        profile.enabled = true;

        for (PetRegion region : definition.getRegions())
        {
            profile.colours.put(region.getKey(), region.getDefaultColour().getRGB());
        }

        return profile;
    }

    public PetProfile copy(String newName)
    {
        PetProfile copy = new PetProfile();
        copy.id = UUID.randomUUID().toString();
        copy.petKey = petKey;
        copy.name = newName;
        copy.enabled = false;
        copy.colours = new LinkedHashMap<>(colours);
        copy.overriddenRegions =
                overriddenRegions == null
                        ? null
                        : new LinkedHashSet<>(overriddenRegions);

        copy.regionNames =
                regionNames == null
                        ? new LinkedHashMap<>()
                        : new LinkedHashMap<>(regionNames);

        return copy;
    }

    public String getId() { return id; }
    public String getPetKey() { return petKey; }
    public String getName() { return name; }
    public boolean isEnabled() { return enabled; }

    public void setName(String name) { this.name = name; }
    public void setEnabled(boolean enabled) { this.enabled = enabled; }

    public Color getColour(PetRegion region)
    {
        Integer rgb = colours.get(region.getKey());
        return rgb == null ? region.getDefaultColour() : new Color(rgb, true);
    }

    public String getRegionName(PetRegion region)
    {
        if (regionNames == null)
        {
            regionNames = new LinkedHashMap<>();
        }

        String custom =
                regionNames.get(
                        region.getKey()
                );

        if (custom == null
                || custom.trim().isEmpty())
        {
            return region.getName();
        }

        return custom;
    }

    public void setRegionName(
            PetRegion region,
            String name)
    {
        if (regionNames == null)
        {
            regionNames = new LinkedHashMap<>();
        }

        String trimmed =
                name == null
                        ? ""
                        : name.trim();

        if (trimmed.isEmpty()
                || trimmed.equals(region.getName()))
        {
            regionNames.remove(region.getKey());
        }
        else
        {
            regionNames.put(
                    region.getKey(),
                    trimmed
            );
        }
    }

    public void setColour(PetRegion region, Color colour)
    {
        colours.put(region.getKey(), colour.getRGB());

        if (overriddenRegions == null)
        {
            overriddenRegions = new LinkedHashSet<>();
        }

        overriddenRegions.add(region.getKey());
    }

    public boolean isColourOverridden(PetRegion region)
    {
        if (overriddenRegions != null)
        {
            return overriddenRegions.contains(region.getKey());
        }

        Integer rgb = colours.get(region.getKey());

        return rgb != null
                && rgb != region.getDefaultColour().getRGB();
    }

    public int colourHash(PetDefinition definition)
    {
        int result = 1;
        for (PetRegion region : definition.getRegions())
        {
            result = 31 * result + getColour(region).getRGB();
        }
        return result;
    }
}

