    public void refresh()
    {
        if (!SwingUtilities
                .isEventDispatchThread())
        {
            SwingUtilities
                    .invokeLater(
                            this::refresh
                    );

            return;
        }

        content.removeAll();

        String filter =
                searchField
                        .getText()
                        .trim()
                        .toLowerCase();

        boolean addedAnything =
                false;

        for (PetProfile profile
                : profileManager
                .getProfiles())
        {
            PetDefinition definition =
                    PetDefinitions.byKey(
                            profile.getPetKey()
                    );

            if (definition == null)
            {
                continue;
            }

            if (!filter.isEmpty()
                    && !definition
                    .getName()
                    .toLowerCase()
                    .contains(filter)
                    && !profile
                    .getName()
                    .toLowerCase()
                    .contains(filter))
            {
                continue;
            }

            JPanel card =
                    buildProfileCard(
                            profile,
                            definition
                    );

            card.setAlignmentX(
                    LEFT_ALIGNMENT
            );

            content.add(card);

            content.add(
                    Box.createVerticalStrut(
                            8
                    )
            );

            addedAnything = true;
        }

        if (!addedAnything)
        {
            JLabel empty =
                    new JLabel(
                            "<html><center>"
                                    + "No matching profiles.<br>"
                                    + "Create one for a supported pet."
                                    + "</center></html>",
                            SwingConstants.CENTER
                    );

            empty.setForeground(
                    Color.LIGHT_GRAY
            );

            empty.setBorder(
                    new EmptyBorder(
                            18,
                            8,
                            8,
                            8
                    )
            );

            empty.setAlignmentX(
                    CENTER_ALIGNMENT
            );

            content.add(empty);
        }

        content.add(
                Box.createVerticalGlue()
        );

        content.revalidate();
        content.repaint();
    }

    private JPanel buildProfileCard(
            PetProfile profile,
            PetDefinition definition)
    {
        JPanel card =
                new JPanel()
                {
                    @Override
                    protected void paintComponent(
                            Graphics graphics)
                    {
                        Graphics2D g2 =
                                (Graphics2D) graphics.create();

                        g2.setRenderingHint(
                                RenderingHints.KEY_ANTIALIASING,
                                RenderingHints.VALUE_ANTIALIAS_ON
                        );

                        GradientPaint upperStone =
                                new GradientPaint(
                                        0,
                                        0,
                                        new Color(
                                                28,
                                                28,
                                                26
                                        ),
                                        0,
                                        getHeight() / 2f,
                                        new Color(
                                                43,
                                                42,
                                                38
                                        )
                                );

                        g2.setPaint(
                                upperStone
                        );

                        g2.fillRoundRect(
                                0,
                                0,
                                getWidth(),
                                getHeight(),
                                12,
                                12
                        );

                        GradientPaint lowerStone =
                                new GradientPaint(
                                        0,
                                        getHeight() / 2f,
                                        new Color(
