                                );

                        g2.setPaint(
                                lowerStone
                        );

                        g2.fillRoundRect(
                                0,
                                getHeight() / 2,
                                getWidth(),
                                getHeight() / 2 + 1,
                                12,
                                12
                        );

                        g2.setColor(
                                new Color(
