    private void deleteProfile(
            PetProfile profile)
    {
        int answer =
                JOptionPane.showConfirmDialog(
                        this,
                        "Are you sure you want to delete this pet profile?",
                        "Delete pet profile",
                        JOptionPane.YES_NO_OPTION
                );

        if (answer
                != JOptionPane.YES_OPTION)
        {
            return;
        }

        profileManager.delete(
                profile
        );

        collapsedProfiles.remove(
                profile.getId()
        );

        refresh();
    }

    private void attachProfileContextMenu(
            java.awt.Component component,
            PetProfile profile)
    {
        JPopupMenu menu =
                new JPopupMenu();

        JMenuItem deleteItem =
                new JMenuItem(
                        "Delete"
                );

        deleteItem.addActionListener(
                e -> deleteProfile(
                        profile
                )
        );

        menu.add(
                deleteItem
        );

        if (component
                instanceof javax.swing.JComponent)
        {
            ((javax.swing.JComponent) component)
                    .setComponentPopupMenu(
                            menu
                    );
        }

        if (component
                instanceof java.awt.Container)
        {
            for (java.awt.Component child
                    : ((java.awt.Container) component)
                    .getComponents())
            {
                attachProfileContextMenu(
                        child,
                        profile
                );
            }
        }
    }

    private void exportProfileToFile(
            PetProfile profile)
    {
        JFileChooser chooser =
                createProfileFileChooser();

        chooser.setDialogTitle(
                "Export Pet Palette Profile"
        );

        chooser.setSelectedFile(
                new File(
                        sanitiseFileName(
                                profile.getName()
                        )
                                + ".petpalette"
                )
        );

        int result =
                chooser.showSaveDialog(
                        this
                );

        if (result
                != JFileChooser.APPROVE_OPTION)
        {
            return;
        }

        File file =
                ensureProfileExtension(
                        chooser.getSelectedFile()
                );

        if (file.exists())
        {
            int overwrite =
                    JOptionPane.showConfirmDialog(
                            this,
                            "That file already exists.\nOverwrite it?",
                            "Export profile",
                            JOptionPane.YES_NO_OPTION
                    );

            if (overwrite
                    != JOptionPane.YES_OPTION)
            {
                return;
            }
        }

        try
        {
            String json =
                    profileManager.exportProfileJson(
                            profile
                    );

            Files.write(
                    file.toPath(),
                    json.getBytes(
                            StandardCharsets.UTF_8
                    )
            );

            JOptionPane.showMessageDialog(
                    this,
                    "Profile exported to:\n"
                            + file.getAbsolutePath(),
                    "Profile exported",
                    JOptionPane.INFORMATION_MESSAGE
            );
        }
        catch (Exception ex)
        {
            JOptionPane.showMessageDialog(
                    this,
                    ex.getMessage() == null
                            ? ex.toString()
                            : ex.getMessage(),
                    "Unable to export profile",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

    private void importProfileFromFile()
    {
        JFileChooser chooser =
                createProfileFileChooser();

        chooser.setDialogTitle(
                "Import Pet Palette Profile"
        );

        int result =
                chooser.showOpenDialog(
                        this
                );

        if (result
                != JFileChooser.APPROVE_OPTION)
        {
            return;
        }

        try
        {
            String json =
                    Files.readString(
                            chooser.getSelectedFile().toPath(),
                            StandardCharsets.UTF_8
                    );

            PetProfile imported =
                    profileManager.importProfileJson(
                            json
                    );

            collapsedProfiles.put(
                    imported.getId(),
                    false
            );

            searchField.setText(
                    ""
            );

            refresh();

            JOptionPane.showMessageDialog(
                    this,
                    "Imported \""
                            + imported.getName()
                            + "\".\n"
                            + "It has been added disabled so you can review it first.",
                    "Profile imported",
                    JOptionPane.INFORMATION_MESSAGE
            );
        }
        catch (Exception ex)
        {
            JOptionPane.showMessageDialog(
                    this,
                    ex.getMessage() == null
                            ? ex.toString()
                            : ex.getMessage(),
                    "Unable to import profile",
                    JOptionPane.ERROR_MESSAGE
            );
        }
    }

    private JFileChooser createProfileFileChooser()
    {
        File desktop =
                new File(
                        System.getProperty(
                                "user.home"
                        ),
                        "Desktop"
                );

        JFileChooser chooser =
                desktop.isDirectory()
                        ? new JFileChooser(
                        desktop
                )
                        : new JFileChooser();

        chooser.setAcceptAllFileFilterUsed(
                false
        );

        chooser.setFileFilter(
                new FileNameExtensionFilter(
                        "Pet Palette profile (*.petpalette)",
                        "petpalette"
                )
        );

        return chooser;
    }

    private File ensureProfileExtension(
            File file)
    {
        if (file.getName()
                .toLowerCase()
                .endsWith(
                        ".petpalette"
                ))
        {
            return file;
        }

        return new File(
                file.getParentFile(),
                file.getName()
                        + ".petpalette"
        );
    }

    private String sanitiseFileName(
            String name)
    {
        String cleaned =
                name == null
                        ? "pet-profile"
                        : name.trim()
                        .replaceAll(
                                "[\\\\/:*?\"<>|]",
                                "_"
                        );

        return cleaned.isEmpty()
                ? "pet-profile"
                : cleaned;
    }

    private JButton makeColourButton(
            PetProfile profile,
            PetRegion region)
    {
        JButton button =
                new JButton();

        Dimension swatchSize =
                new Dimension(
                        SWATCH_WIDTH,
                        SWATCH_HEIGHT
                );

        button.setPreferredSize(
                swatchSize
        );

        button.setMinimumSize(
                swatchSize
        );

        button.setMaximumSize(
                swatchSize
        );

        button.setBackground(
                profile.getColour(
                        region
                )
        );

        button.setOpaque(true);
        button.setBorderPainted(true);
        button.setFocusPainted(false);

        button.setBorder(
                BorderFactory
                        .createLineBorder(
                                ColorScheme
                                        .MEDIUM_GRAY_COLOR
                        )
        );

        button.setToolTipText(
                "Change "
                        + profile.getRegionName(
                        region
                )
        );

        button.addActionListener(
                e ->
                {
                    RuneliteColorPicker picker =
                            colorPickerManager
                                    .create(
                                            this,
                                            profile
                                                    .getColour(
                                                            region
                                                    ),
                                            profile.getRegionName(
                                                    region
                                            ),
                                            true
                                    );

                    picker.setOnColorChange(
                            colour ->
                            {
                                profile.setColour(
                                        region,
                                        colour
                                );

                                profileManager
                                        .profileChanged();

                                SwingUtilities
                                        .invokeLater(
                                                () ->
                                                {
                                                    button
                                                            .setBackground(
                                                                    colour
                                                            );

                                                    button
                                                            .repaint();
                                                }
                                        );
                            }
                    );

                    picker.setOnClose(
                            colour ->
                            {
                                profile.setColour(
                                        region,
                                        colour
                                );

                                profileManager
                                        .profileChanged();

                                SwingUtilities
                                        .invokeLater(
                                                this::refresh
                                        );
                            }
                    );

                    picker.setVisible(
                            true
                    );
                }
        );

        return button;
    }

