                                        8
                                )
                        )
        );

        DefaultListModel<PetDefinition>
                listModel =
                new DefaultListModel<>();

        JList<PetDefinition> petList =
                new JList<>(
                        listModel
                );

        petList.setSelectionMode(
                ListSelectionModel
                        .SINGLE_SELECTION
        );


        petList.setCellRenderer(
                (list, value, index, isSelected, cellHasFocus) ->
                {
                    JLabel label =
                            new JLabel(
                                    value == null
                                            ? ""
                                            : value.getName()
                            );

                    label.setOpaque(
                            true
                    );

                    label.setBorder(
                            new EmptyBorder(
                                    5,
                                    8,
                                    5,
                                    8
                            )
                    );

                    label.setBackground(
                            isSelected
                                    ? ColorScheme.MEDIUM_GRAY_COLOR
                                    : ColorScheme.DARKER_GRAY_COLOR
                    );

                    label.setForeground(
                            Color.WHITE
                    );

                    return label;
                }
        );

        petList.setBackground(
                ColorScheme.DARKER_GRAY_COLOR
        );

        petList.setForeground(
                Color.WHITE
        );

        petList.setSelectionBackground(
                ColorScheme.MEDIUM_GRAY_COLOR
        );

        petList.setSelectionForeground(
                Color.WHITE
        );

        JScrollPane petScroll =
                new JScrollPane(
                        petList
                );

        petScroll.setPreferredSize(
                new Dimension(
                        320,
                        360
                )
        );

        petScroll.setBorder(
                BorderFactory
                        .createLineBorder(
                                ColorScheme
                                        .MEDIUM_GRAY_COLOR
                        )
        );

        Runnable rebuildList =
                () ->
                {
                    String filter =
                            petSearch
                                    .getText()
                                    .trim()
                                    .toLowerCase();

                    listModel.clear();

                    for (PetDefinition definition
                            : PetDefinitions.all())
                    {
                        if (filter.isEmpty()
                                || definition
                                .getName()
                                .toLowerCase()
                                .contains(filter))
                        {
                            listModel.addElement(
                                    definition
                            );
                        }
                    }

                    if (!listModel.isEmpty())
                    {
                        petList.setSelectedIndex(
                                0
                        );

                        petList.ensureIndexIsVisible(
                                0
                        );
                    }
                };

        petSearch
                .getDocument()
                .addDocumentListener(
                        new DocumentListener()
                        {
                            @Override
                            public void insertUpdate(
                                    DocumentEvent e)
                            {
                                rebuildList.run();
                            }

                            @Override
                            public void removeUpdate(
                                    DocumentEvent e)
                            {
                                rebuildList.run();
                            }

                            @Override
                            public void changedUpdate(
                                    DocumentEvent e)
                            {
                                rebuildList.run();
                            }
                        }
                );

        JButton create =
                new JButton(
                        "Create"
                );

        JButton cancel =
                new JButton(
                        "Cancel"
                );

        PetDefinition[] result =
                new PetDefinition[1];

        Runnable acceptSelection =
                () ->
                {
                    PetDefinition definition =
                            petList
                                    .getSelectedValue();

                    if (definition == null)
                    {
                        return;
                    }

                    result[0] =
                            definition;

                    dialog.dispose();
                };

        create.addActionListener(
                e -> acceptSelection.run()
        );

        cancel.addActionListener(
                e -> dialog.dispose()
        );

        petSearch.addActionListener(
                e -> acceptSelection.run()
        );

        petList.addMouseListener(
                new java.awt.event.MouseAdapter()
                {
                    @Override
                    public void mouseClicked(
                            java.awt.event.MouseEvent e)
                    {
                        if (e.getClickCount() == 2
                                && petList
                                .getSelectedValue()
                                != null)
                        {
                            acceptSelection.run();
                        }
                    }
                }
        );

        JPanel buttons =
                new JPanel(
                        new FlowLayout(
                                FlowLayout.RIGHT,
                                5,
                                0
                        )
                );

        buttons.setBackground(
                ColorScheme.DARK_GRAY_COLOR
        );

        buttons.add(
                cancel
        );

        buttons.add(
                create
        );

        root.add(
                petSearch,
                BorderLayout.NORTH
        );

        root.add(
                petScroll,
                BorderLayout.CENTER
        );

        root.add(
                buttons,
                BorderLayout.SOUTH
        );

        dialog.setContentPane(
                root
        );

        dialog.pack();
        dialog.setLocationRelativeTo(
                this
        );

        rebuildList.run();

        SwingUtilities.invokeLater(
                petSearch::requestFocusInWindow
        );

        dialog.setVisible(
                true
        );

        return result[0];
    }

    private static class PlaceholderTextField
            extends JTextField
    {
        private final String placeholder;
        private final Color placeholderForeground =
                Color.GRAY;

        private PlaceholderTextField(
                String placeholder)
        {
            this.placeholder =
                    placeholder;
        }

        @Override
        protected void paintComponent(
                Graphics graphics)
        {
            super.paintComponent(
                    graphics
            );

            if (!getText().isEmpty())
            {
                return;
            }

            Graphics copy =
                    graphics.create();

            try
            {
                copy.setColor(
                        placeholderForeground
                );

                Insets insets =
                        getInsets();

                int y =
                        (
                                getHeight()
                                        - getFontMetrics(
                                        getFont()
                                )
                                        .getHeight()
                        ) / 2
                                + getFontMetrics(
                                getFont()
                        )
                                .getAscent();

                copy.drawString(
                        placeholder,
                        insets.left,
                        y
                );
            }
            finally
            {
                copy.dispose();
            }
        }
    }

    private static class ScrollableContentPanel
            extends JPanel
            implements Scrollable
    {
        @Override
        public Dimension
        getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(
                Rectangle visibleRect,
                int orientation,
                int direction)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(
                Rectangle visibleRect,
                int orientation,
                int direction)
        {
            return Math.max(
                    16,
                    visibleRect.height - 16
            );
        }

        @Override
        public boolean
        getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean
        getScrollableTracksViewportHeight()
        {
            return false;
        }
    }
}

