package com.petpalette;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class PetProfileManager
{
    private static final String GROUP = "petpaletteer";
    private static final String KEY = "profiles";
    private static final int PROFILE_EXPORT_VERSION = 1;

    private static final Type PROFILE_LIST_TYPE =
            new TypeToken<List<PetProfile>>() { }.getType();

    private final ConfigManager configManager;
    private final Gson gson;

    private List<PetProfile> profiles = new ArrayList<>();
    private int revision = 0;

    private static final class ExportedPetProfile
    {
        private int formatVersion;
        private PetProfile profile;

        private ExportedPetProfile()
        {
            // Gson
        }

        private ExportedPetProfile(
                int formatVersion,
                PetProfile profile)
        {
            this.formatVersion = formatVersion;
            this.profile = profile;
        }
    }

    @Inject
    public PetProfileManager(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    public synchronized void load()
    {
        String json = configManager.getConfiguration(GROUP, KEY);

        if (json == null || json.trim().isEmpty())
        {
            profiles = new ArrayList<>();
            revision++;
            return;
        }

        try
        {
            List<PetProfile> loaded = gson.fromJson(json, PROFILE_LIST_TYPE);
            profiles = loaded == null ? new ArrayList<>() : new ArrayList<>(loaded);
        }
        catch (Exception ex)
        {
            profiles = new ArrayList<>();
        }

        revision++;
    }

    public synchronized List<PetProfile> getProfiles()
    {
        return List.copyOf(profiles);
    }

    public synchronized List<PetProfile> getProfilesForPet(String petKey)
    {
        List<PetProfile> result = new ArrayList<>();

        for (PetProfile profile : profiles)
        {
            if (petKey.equals(profile.getPetKey()))
            {
                result.add(profile);
            }
        }

        return result;
    }

    public synchronized PetProfile getActiveProfile(String petKey)
    {
        for (PetProfile profile : profiles)
        {
            if (petKey.equals(profile.getPetKey()) && profile.isEnabled())
            {
                return profile;
            }
        }
        return null;
    }

    public synchronized void createProfile(PetDefinition definition)
    {
        int number = getProfilesForPet(definition.getKey()).size() + 1;
        PetProfile profile = PetProfile.create(definition, definition.getName() + " " + number);

        disableAllForPet(definition.getKey());
        profile.setEnabled(true);
        profiles.add(profile);
        save();
    }

    public synchronized void duplicate(PetProfile source)
    {
        PetProfile copy = source.copy(source.getName() + " copy");
        profiles.add(copy);
        save();
    }

    public synchronized void delete(PetProfile profile)
    {
        profiles.removeIf(p -> p.getId().equals(profile.getId()));
        save();
    }

    public synchronized void rename(PetProfile profile, String newName)
    {
        if (newName == null || newName.trim().isEmpty())
        {
            return;
        }

        profile.setName(newName.trim());
        save();
    }

    public synchronized void setEnabled(PetProfile profile, boolean enabled)
    {
        if (enabled)
        {
            disableAllForPet(profile.getPetKey());
        }

        profile.setEnabled(enabled);
        save();
    }

    public synchronized void renameRegionForPet(
            PetProfile sourceProfile,
            PetRegion region,
            String newName)
    {
        if (sourceProfile == null
                || region == null)
        {
            return;
        }

        String petKey = sourceProfile.getPetKey();

        for (PetProfile profile : profiles)
        {
            if (petKey.equals(profile.getPetKey()))
            {
                profile.setRegionName(region, newName);
            }
        }

        save();
    }

    public synchronized void profileChanged()
    {
        save();
    }

    public synchronized String exportProfileJson(PetProfile profile)
    {
        if (profile == null)
        {
            throw new IllegalArgumentException("Profile cannot be null.");
        }

        return gson.toJson(
                new ExportedPetProfile(
                        PROFILE_EXPORT_VERSION,
                        profile
                )
        );
    }

    public synchronized PetProfile importProfileJson(String json)
    {
        if (json == null || json.trim().isEmpty())
        {
            throw new IllegalArgumentException("The profile file is empty.");
        }

        final ExportedPetProfile exported;

        try
        {
            exported = gson.fromJson(json, ExportedPetProfile.class);
        }
        catch (Exception ex)
        {
            throw new IllegalArgumentException(
                    "This is not a valid Pet Palette profile file.",
                    ex
            );
        }

        if (exported == null || exported.profile == null)
        {
            throw new IllegalArgumentException(
                    "The file does not contain a Pet Palette profile."
            );
        }

        if (exported.formatVersion <= 0
                || exported.formatVersion > PROFILE_EXPORT_VERSION)
        {
            throw new IllegalArgumentException(
                    "This profile file uses an unsupported format version."
            );
        }

        PetDefinition definition =
                PetDefinitions.byKey(exported.profile.getPetKey());

        if (definition == null)
        {
            throw new IllegalArgumentException(
                    "This profile is for an unsupported pet: "
                            + exported.profile.getPetKey()
            );
        }

        String baseName =
                exported.profile.getName() == null
                        || exported.profile.getName().trim().isEmpty()
                        ? definition.getName()
                        : exported.profile.getName().trim();

        String uniqueName = makeUniqueProfileName(baseName);

        PetProfile imported = exported.profile.copy(uniqueName);
        imported.setEnabled(false);
        profiles.add(imported);
        save();

        return imported;
    }

    private String makeUniqueProfileName(String requestedName)
    {
        String base =
                requestedName == null
                        || requestedName.trim().isEmpty()
                        ? "Imported profile"
                        : requestedName.trim();

        if (!profileNameExists(base))
        {
            return base;
        }

        int number = 2;

        while (profileNameExists(base + " (" + number + ")"))
        {
            number++;
        }

        return base + " (" + number + ")";
    }

    private boolean profileNameExists(String name)
    {
        for (PetProfile profile : profiles)
        {
            if (profile.getName() != null
                    && profile.getName().equalsIgnoreCase(name))
            {
                return true;
            }
        }

        return false;
    }

    public synchronized int getRevision()
    {
        return revision;
    }

    private void disableAllForPet(String petKey)
    {
        for (PetProfile profile : profiles)
        {
            if (petKey.equals(profile.getPetKey()))
            {
                profile.setEnabled(false);
            }
        }
    }

    private void save()
    {
        configManager.setConfiguration(GROUP, KEY, gson.toJson(profiles));
        revision++;
    }
}

package com.petpalette;

import java.util.Collections;
import java.util.List;
import java.util.Map;

public class PetDefinition
{
    private final String key;
    private final String name;
    private final int[] npcIds;
    private final int itemId;
    private final int[] modelIds;
    private final int widthScale;
    private final int heightScale;
    private final int yOffset;
    private final String mainRegionKey;
    private final List<PetRegion> regions;
    private final Map<Short, Short> nativeRecolours;

    public PetDefinition(
            String key,
            String name,
            int[] npcIds,
            int itemId,
            int[] modelIds,
            int widthScale,
            int heightScale,
            int yOffset,
            String mainRegionKey,
            List<PetRegion> regions,
            Map<Short, Short> nativeRecolours)
    {
        this.key = key;
        this.name = name;
        this.npcIds = npcIds.clone();
        this.itemId = itemId;
        this.modelIds = modelIds.clone();
        this.widthScale = widthScale;
        this.heightScale = heightScale;
        this.yOffset = yOffset;
        this.mainRegionKey = mainRegionKey;
        this.regions = Collections.unmodifiableList(regions);
        this.nativeRecolours = Collections.unmodifiableMap(nativeRecolours);
    }

    public String getKey()
    {
        return key;
    }

    public String getName()
    {
        return name;
    }

    public int getItemId()
    {
        return itemId;
    }

    public int[] getModelIds()
    {
        return modelIds.clone();
    }

    public int getWidthScale()
    {
        return widthScale;
    }

    public int getHeightScale()
    {
        return heightScale;
    }

    public int getYOffset()
    {
        return yOffset;
    }

    public String getMainRegionKey()
    {
        return mainRegionKey;
    }

    public List<PetRegion> getRegions()
    {
        return regions;
    }

    public Map<Short, Short> getNativeRecolours()
    {
        return nativeRecolours;
    }

    public boolean matchesNpcId(int npcId)
    {
        for (int id : npcIds)
        {
            if (id == npcId)
            {
                return true;
            }
        }

        return false;
    }
}

