                    )
            );

    private PetDefinitions()
    {
    }

    public static List<PetDefinition> all()
    {
        return ALL;
    }

    public static PetDefinition byKey(String key)
    {
        for (PetDefinition definition : ALL)
        {
            if (definition.getKey().equals(key))
            {
                return definition;
            }
        }
        return null;
    }

    public static PetDefinition byNpcId(int npcId)
    {
        for (PetDefinition definition : ALL)
        {
            if (definition.matchesNpcId(npcId))
            {
                return definition;
            }
        }
        return null;
    }
}

package com.petpalette;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.RuneLiteObject;

import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameTick;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
        name = "Pet Palette",
        description = "Client-side cosmetic recolours for pets"
)
public class PetPalettePlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private PetPaletteConfig config;

    @Inject
    private PetProfileManager profileManager;

    @Inject
    private PetPalettePanel panel;
    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ClientThread clientThread;

    private NavigationButton navButton;

    private final Map<NPC, PaletteInstance> palettePets =
            new IdentityHashMap<>();

    private final Set<RuneLiteObject> spawnedObjects =
            Collections.newSetFromMap(
                    new IdentityHashMap<>()
            );

    private final Map<int[], int[]> hiddenRealFaceColours =
            new IdentityHashMap<>();

    @Override
    protected void startUp()
    {
        profileManager.load();

        navButton = NavigationButton.builder()
                .tooltip("Pet Palette")
                .icon(
                        ImageUtil.loadImageResource(
                                PetPalettePlugin.class,
                                "panel_icon.png"
                        )
                )
                .priority(5)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
        SwingUtilities.invokeLater(panel::refresh);

        log.info("Pet Palette profile system started");
    }

    @Override
    protected void shutDown()
    {

        clientThread.invokeLater(() ->
        {
            restoreRealPetFaces();
            removeAllPalettePets();
            removeAnySpawnedObjects();
        });

        if (navButton != null)
        {
            clientToolbar.removeNavigation(navButton);
            navButton = null;
        }

        log.info("Pet Palette stopped");
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.enabled())
        {
            restoreRealPetFaces();
            removeAllPalettePets();
            return;
        }

        syncVisiblePets();
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (!config.enabled())
        {
            restoreRealPetFaces();
            removeAllPalettePets();
            return;
        }

        syncVisiblePets();

        NPC follower = client.getFollower();
        if (follower != null && palettePets.containsKey(follower))
        {
            hideRealPetFaces(follower);
        }
        else
        {
            restoreRealPetFaces();
        }

        for (PaletteInstance instance : palettePets.values())
        {
            NPC npc = instance.npc;

            if (npc == null)
            {
                continue;
            }

            PetProfile profile =
                    profileManager.getActiveProfile(
                            instance.definition.getKey()
                    );

            if (profile == null)
            {
                continue;
            }

            int fingerprint =
                    getAppearanceFingerprint(
                            instance.definition,
                            profile
                    );

            if (fingerprint != instance.appearanceFingerprint)
            {
                Model rebuilt = buildBaseModel(
                        instance.npc,
                        instance.definition,
                        profile
                );

                if (rebuilt != null)
                {
                    instance.baseModel = rebuilt;
                    instance.appearanceFingerprint = fingerprint;
                }
            }
        }
    }

    private void syncVisiblePets()
    {
        NPC follower = client.getFollower();

        if (follower == null || follower.getComposition() == null)
        {
            removeAllPalettePets();
            return;
        }

        PetDefinition definition =
                PetDefinitions.byNpcId(follower.getId());

        if (definition == null)
        {
            removeAllPalettePets();
            return;
        }

        PetProfile activeProfile =
                profileManager.getActiveProfile(
                        definition.getKey()
                );

        if (activeProfile == null)
        {
            removeAllPalettePets();
            return;
        }

        Iterator<Map.Entry<NPC, PaletteInstance>> iterator =
                palettePets.entrySet().iterator();

        while (iterator.hasNext())
        {
            Map.Entry<NPC, PaletteInstance> entry =
                    iterator.next();

            if (entry.getKey() != follower)
            {
                removePalettePet(entry.getValue());
                iterator.remove();
            }
        }

        PaletteInstance instance =
                palettePets.get(follower);

        if (instance == null)
        {
            createPalettePet(
                    follower,
                    definition
            );
        }
        else if (!instance.definition.getKey().equals(definition.getKey()))
        {
            removePalettePet(instance);
            palettePets.remove(follower);

            createPalettePet(
                    follower,
                    definition
            );
        }
    }

    private int getAppearanceFingerprint(
            PetDefinition definition,
            PetProfile profile)
    {
        if (profile == null)
        {
            return Objects.hash(
                    definition.getKey(),
                    "native",
                    profileManager.getRevision()
            );
        }

        return Objects.hash(
                definition.getKey(),
                profile.getId(),
                profile.colourHash(definition),
                profileManager.getRevision()
        );
    }

    private void createPalettePet(
            NPC npc,
            PetDefinition definition)
    {
        PetProfile profile =
                profileManager.getActiveProfile(
                        definition.getKey()
                );

        if (profile == null)
        {
            return;
        }

        Model baseModel =
                buildBaseModel(
                        npc,
                        definition,
                        profile
                );

        if (baseModel == null)
        {
            return;
        }

        PaletteInstance instance =
                new PaletteInstance(
                        npc,
                        definition,
                        baseModel,
                        getAppearanceFingerprint(definition, profile)
                );

        RuneLiteObject object =
                new RuneLiteObject(client)
                {
                    @Override
                    public void tick(int ticksSinceLastFrame)
                    {
                        super.tick(ticksSinceLastFrame);

                        NPC realPet = instance.npc;

                        if (realPet == null
                                || !instance.definition.matchesNpcId(realPet.getId()))
                        {
                            return;
                        }

                        setLocation(
                                realPet.getLocalLocation(),
                                client.getTopLevelWorldView().getPlane()
                        );

                        setOrientation(
                                realPet.getCurrentOrientation()
                        );
                    }

                    @Override
                    public Model getModel()
                    {
                        NPC realPet = instance.npc;
                        Model model = instance.baseModel;

                        if (realPet == null
                                || !instance.definition.matchesNpcId(realPet.getId())
                                || model == null)
                        {
                            return null;
                        }

                        int actionId = realPet.getAnimation();
                        int actionFrame = realPet.getAnimationFrame();
                        Animation actionAnimation = null;

                        if (actionId != -1 && actionFrame != -1)
                        {
                            actionAnimation = client.loadAnimation(actionId);
                        }

                        int poseId = realPet.getPoseAnimation();
                        int poseFrame = realPet.getPoseAnimationFrame();
                        Animation poseAnimation = null;

                        if (poseId != -1 && poseFrame != -1)
                        {
                            poseAnimation = client.loadAnimation(poseId);
                        }

                        return client.applyTransformations(
                                model,
                                actionAnimation,
                                actionFrame,
                                poseAnimation,
                                poseFrame
                        );
                    }
                };

        instance.object = object;

        object.setLocation(
                npc.getLocalLocation(),
                client.getTopLevelWorldView().getPlane()
        );
        object.setOrientation(npc.getCurrentOrientation());

        spawnedObjects.add(object);
        object.setActive(true);

        palettePets.put(npc, instance);
        log.debug(
                "Created Pet Palette model for visible {} [{}] using {}",
                definition.getName(),
                npc.getId(),
                profile.getName()
        );
    }

    private Model buildBaseModel(
            NPC npc,
            PetDefinition definition,
            PetProfile profile)
    {

        int[] modelIds;

        if ("beaver".equals(definition.getKey())
                && npc != null
                && npc.getComposition() != null
                && npc.getComposition().getModels() != null
                && npc.getComposition().getModels().length > 0)
        {
            modelIds = npc.getComposition().getModels();
        }
        else
        {
            modelIds = definition.getModelIds();
        }

        ModelData[] parts = new ModelData[modelIds.length];

        for (int i = 0; i < modelIds.length; i++)
        {
            ModelData part = client.loadModelData(modelIds[i]);

            if (part == null)
            {
                log.debug(
                        "ModelData {} is not available for {}",
                        modelIds[i],
                        definition.getName()
                );
                return null;
            }

            parts[i] = part.cloneColors();
        }

        if ("beaver".equals(definition.getKey()))
        {
            applyBeaverFaceIndexColours(
                    parts,
                    definition,
                    profile
            );
        }
        else
        {
            NPCComposition composition =
                    npc == null
                            ? null
                            : npc.getTransformedComposition();

            if (composition == null && npc != null)
            {
                composition = npc.getComposition();
            }

            short[] nativeFind =
                    composition == null
                            ? null
                            : composition.getColorToReplace();

            short[] nativeReplace =
                    composition == null
                            ? null
                            : composition.getColorToReplaceWith();

            for (PetRegion region : definition.getRegions())
            {
                short source =
                        region.getSourceColour();

                if (profile.isColourOverridden(region))
                {
                    recolourAll(
                            parts,
                            source,
                            profile.getColour(region)
                    );
                }
                else
                {
                    short nativeDestination =
                            findNativeReplacement(
                                    source,
                                    nativeFind,
                                    nativeReplace
                            );

                    if (nativeDestination != source)
                    {
                        recolourAll(
                                parts,
                                source,
                                nativeDestination
                        );
                    }
                }
            }
        }

        ModelData merged = client.mergeModels(parts);

        if (merged == null)
        {
            log.debug("Failed to merge model for {}", definition.getName());
            return null;
        }

        merged.scale(
                definition.getWidthScale(),
                definition.getHeightScale(),
                definition.getWidthScale()
        );

        merged.translate(0, definition.getYOffset(), 0);
        return merged.light();
    }

    private void applyBeaverFaceIndexColours(
            ModelData[] variantParts,
            PetDefinition definition,
            PetProfile profile)
    {
        if (variantParts.length != 1)
        {
            log.debug(
                    "Beaver face-index mapping expected 1 model part but found {}",
                    variantParts.length
            );
            return;
        }

        ModelData canonicalLoaded =
                client.loadModelData(29754);

        if (canonicalLoaded == null)
        {
            log.debug("Normal Beaver canonical model 29754 is not available");
            return;
        }

        ModelData canonical =
                canonicalLoaded.cloneColors();

        short[] canonicalColours =
                canonical.getFaceColors();

        short[] variantColours =
                variantParts[0].getFaceColors();

        if (canonicalColours == null
                || variantColours == null)
        {
            return;
        }

        if (canonicalColours.length != variantColours.length)
        {
            log.debug(
                    "Beaver topology mismatch: canonical faces={} variant faces={}",
                    canonicalColours.length,
                    variantColours.length
            );
            return;
        }

        for (PetRegion region : definition.getRegions())
        {

            if (!profile.isColourOverridden(region))
            {
                continue;
            }

            short canonicalSource =
                    region.getSourceColour();

            short destination =
                    JagexColor.rgbToHSL(
                            profile.getColour(region).getRGB(),
                            1.0
                    );

            for (int face = 0;
                 face < canonicalColours.length;
                 face++)
            {
                if (canonicalColours[face] == canonicalSource)
                {
                    variantColours[face] =
                            destination;
                }
            }
        }
    }

    private short findNativeReplacement(
            short source,
            short[] find,
            short[] replace)
    {
        if (find == null || replace == null)
        {
            return source;
        }

        int length =
                Math.min(
                        find.length,
                        replace.length
                );

        for (int i = 0; i < length; i++)
        {
            if (find[i] == source)
            {
                return replace[i];
            }
        }

        return source;
    }

    private void recolourAll(
            ModelData[] parts,
            short source,
            Color colour)
    {
        short destination =
                JagexColor.rgbToHSL(
                        colour.getRGB(),
                        1.0
                );

        recolourAll(parts, source, destination);
    }

    private void recolourAll(
            ModelData[] parts,
            short source,
            short destination)
    {
        for (ModelData part : parts)
        {
            part.recolor(source, destination);
        }
    }

    private void hideRealPetFaces(NPC follower)
    {
        Model realModel = follower.getModel();

        if (realModel == null)
        {
            return;
        }

        int[] faceColors3 = realModel.getFaceColors3();

        if (faceColors3 == null)
        {
            return;
        }

        hiddenRealFaceColours.computeIfAbsent(
                faceColors3,
                int[]::clone
        );

        java.util.Arrays.fill(
                faceColors3,
                -2
        );
    }

    private void restoreRealPetFaces()
    {
        for (Map.Entry<int[], int[]> entry : hiddenRealFaceColours.entrySet())
        {
            int[] current = entry.getKey();
            int[] original = entry.getValue();

            if (current != null
                    && original != null
                    && current.length == original.length)
            {
                System.arraycopy(
                        original,
                        0,
                        current,
                        0,
                        current.length
                );
            }
        }

        hiddenRealFaceColours.clear();
    }

    private void removePalettePet(PaletteInstance instance)
    {
        if (instance.object != null)
        {
            instance.object.setActive(false);
            spawnedObjects.remove(instance.object);
            instance.object = null;
        }

        instance.baseModel = null;
    }

    private void removeAllPalettePets()
    {
        restoreRealPetFaces();

        for (PaletteInstance instance : palettePets.values())
        {
            removePalettePet(instance);
        }

        palettePets.clear();
    }

    private void removeAnySpawnedObjects()
    {

        for (RuneLiteObject object : spawnedObjects)
        {
            if (object != null && object.isActive())
            {
                object.setActive(false);
            }
        }

        spawnedObjects.clear();
    }

    private static final class PaletteInstance
    {
        private final NPC npc;
        private final PetDefinition definition;
        private RuneLiteObject object;
        private Model baseModel;
        private int appearanceFingerprint;

        private PaletteInstance(
                NPC npc,
                PetDefinition definition,
                Model baseModel,
                int appearanceFingerprint)
        {
            this.npc = npc;
            this.definition = definition;
            this.baseModel = baseModel;
            this.appearanceFingerprint = appearanceFingerprint;
        }
    }

    @Provides
    PetPaletteConfig provideConfig(
            ConfigManager configManager)
    {
        return configManager.getConfig(
                PetPaletteConfig.class
        );
    }
}
